                Claim was = repository.find(id, cid);
                return was == null ? null : new BigDecimal[] { repository.dueNow(id, was) };
            });
            if (then == null) {
                throw new BadRequestException("the claim did not exist on " + on);
            }
            asOfDue = then[0];
        }
