81	            case "open" -> { to = "OPEN"; from = List.of("DRAFT"); event = "CLAIM_OPENED"; }
82	            case "settle" -> { to = "SETTLED"; from = List.of("OPEN"); event = "CLAIM_SETTLED"; }
83	            case "approve" -> { to = "SETTLED"; from = List.of("PENDING"); event = "CLAIM_APPROVED"; }
84	            case "reject" -> { to = "OPEN"; from = List.of("PENDING"); event = "CLAIM_REJECTED"; }
85	            case "review" -> { to = "OPEN"; from = List.of("REVIEW"); event = "CLAIM_OPENED"; }
86	            case "void" -> { to = "VOID"; from = List.of("DRAFT", "REVIEW", "OPEN", "PENDING", "SETTLED"); event = "CLAIM_VOIDED"; }
87	            default -> throw new BadRequestException("no such action");
88	        }
89	        Claim found = repository.find(id, cid);
90	        if (found == null) {
91	            throw new BadRequestException("no such claim");
92	        }
93	        // The claim the four-eyes rules and the proof rule are judged on: the claim itself, or for a part-settle the original.
94	        Claim judged = original != null ? original : found;
95	        if (!from.contains(found.status())) {
96	            throw new BadRequestException("a " + found.status() + " claim cannot be moved to " + to);
97	        }
98	        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
99	        // Open, settle and void go by the sheet's permission matrix; approve and reject stay with stewards (below).
100	        String act = action.trim();
101	        if ((act.equals("open") || act.equals("settle") || act.equals("void")) && !settings.allows(id, act, by)) {
102	            throw new BadRequestException("a " + settings.role(id, by) + " cannot " + act + " a claim");
103	        }
104	        // While its person's flag is in force only a steward opens a claim (alone, in bulk or by a paste).
105	        if (act.equals("open") && !settings.role(id, by).equals(SettingsRepository.STEWARD)
106	                && repository.flagged(id, found.personId())) {
107	            throw new BadRequestException("only a steward can open a claim of a flagged person");
108	        }
109	        // Only a steward reviews a REVIEW claim, making it OPEN.
110	        if (act.equals("review") && !settings.role(id, by).equals(SettingsRepository.STEWARD)) {
111	            throw new BadRequestException("only a steward can review a claim");
112	        }
113	        // Four eyes: whoever opened a claim cannot settle it.
114	        if (to.equals("SETTLED") && found.status().equals("OPEN") && by.equals(judged.openedBy())) {
115	            throw new BadRequestException("the user who opened a claim cannot settle it");
116	        }
117	        // Nor can whoever last edited it settle or approve it.
118	        if (to.equals("SETTLED") && (found.status().equals("OPEN") || found.status().equals("PENDING"))
119	                && by.equals(repository.editedBy(id, judged.id()))) {
120	            throw new BadRequestException("the user who last edited a claim cannot " + act + " it");
121	        }
122	        // A deferred claim cannot be settled until the sheet's today reaches the date it is deferred until.
123	        if (to.equals("SETTLED") && found.deferred()) {
124	            throw new BadRequestException("a claim deferred until " + found.deferredUntil() + " cannot be settled");
125	        }
126	        // Only a steward approves or rejects a PENDING claim, and never one they opened themselves.
127	        if (found.status().equals("PENDING") && !to.equals("VOID")) {
128	            if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
129	                throw new BadRequestException("only a steward can " + action.trim() + " a pending claim");
130	            }
131	            if (to.equals("SETTLED") && by.equals(found.openedBy())) {
132	                throw new BadRequestException("the user who opened a claim cannot approve it");
133	            }
134	        }
135	        // Only a steward voids a SETTLED claim, and only within 7 days of the date its status log settled it.
136	        boolean reversing = found.status().equals("SETTLED") && to.equals("VOID");
137	        if (reversing) {
138	            if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
139	                throw new BadRequestException("only a steward can void a settled claim");
140	            }
141	            Long days = repository.daysSinceSettled(id, cid);
142	            if (days == null || days < 0 || days > 7) {
143	                throw new BadRequestException("a settled claim can be voided only within 7 days of its settlement");
144	            }
145	        }
146	        String why = reason == null ? "" : reason.trim();
147	        if (event.equals("CLAIM_REJECTED") && why.isEmpty()) {
148	            throw new BadRequestException("give a reason to reject the claim");
149	        }
150	        // While the sheet has void reasons, a void needs one chosen from them; with none, a void takes no reason.
151	        String voidReason = null;
152	        if (to.equals("VOID")) {
153	            List<String> reasons = settings.voidReasons(id);
154	            if (!reasons.isEmpty()) {
155	                if (why.isEmpty()) {
156	                    throw new BadRequestException("choose a reason to void the claim");
157	                }
158	                if (!reasons.contains(why)) {
159	                    throw new BadRequestException(why + " is not one of the sheet's void reasons");
160	                }
161	                voidReason = why;
162	            }
163	        }
164	        // A claim whose due is above the note threshold in force on its date cannot be opened with an empty
165	        // note ('n/a' is above none).
166	        if (to.equals("OPEN") && found.status().equals("DRAFT") && (found.note() == null || found.note().trim().isEmpty())) {
167	            BigDecimal threshold = settings.noteThreshold(id, LocalDate.parse(found.date()));
168	            BigDecimal now = repository.dueNow(id, found);
169	            if (threshold != null && now != null && now.compareTo(threshold) > 0) {
170	                throw new BadRequestException("a claim with a due above the note threshold needs a note to be opened");
171	            }
172	        }
173	        // A claim whose due is above the proof threshold in force on its date (its person's grade's then when one
174	        // is set, else the sheet's) cannot be settled or approved without a proof ('n/a' is above none); this is
175	        // decided before the clerk limit. While the sheet has proof kinds, such a claim needs a proof of each.
176	        String kinds = settings.proofKinds(id);
177	        if (to.equals("SETTLED") && (judged.proofs() == 0 || kinds != null)) {
178	            BigDecimal threshold = settings.proofThreshold(id, repository.gradeOn(id, judged), LocalDate.parse(judged.date()));
179	            BigDecimal now = repository.dueNow(id, judged);
180	            if (threshold != null && now != null && now.compareTo(threshold) > 0) {
181	                if (judged.proofs() == 0) {
182	                    throw new BadRequestException("a claim with a due above the proof threshold needs a proof to be settled");
183	                }
184	                for (String kind : kinds.split(",")) {
185	                    if (judged.proofs(kind) == 0) {
186	                        throw new BadRequestException("a claim with a due above the proof threshold needs a " + kind + " proof to be settled");
187	                    }
188	                }
189	            }
190	        }
191	        // A clerk settles outright only a claim whose due is within the clerk limit in force (its person's grade's
192	        // on the sheet's today when one is set, else the sheet's; 'n/a' is within any); above it the claim goes to PENDING for a steward to approve or reject. A steward settles anything.
193	        if (to.equals("SETTLED") && found.status().equals("OPEN")
194	                && settings.role(id, by).equals(SettingsRepository.CLERK)) {
195	            BigDecimal limit = settings.clerkLimit(id, repository.gradeOn(id, found.personId(), settings.today(id)));
196	            BigDecimal now = repository.dueNow(id, found);
197	            if (limit != null && now != null && now.compareTo(limit) > 0) {
198	                to = "PENDING";
199	                event = "CLAIM_PENDING";
200	            }
201	        }
202	        // A period with a cap opens no claim belonging to it (by due-by) for a person who already has that many
203	        // OPEN or PENDING claims in it.
204	        if (to.equals("OPEN") && (found.status().equals("DRAFT") || found.status().equals("REVIEW"))) {
205	            Period in = periods.containing(id, LocalDate.parse(found.dueBy()));
206	            if (in != null && in.cap() != null && periods.openIn(id, found.personId(), in) >= in.cap()) {
207	                throw new BadRequestException("the person already has " + in.cap() + " open claims in the period " + in.name());
208	            }
209	        }
210	        // A claim whose due is above the review threshold in force on its date goes to REVIEW when opened, with
211	        // no number until a steward reviews it ('n/a' is above none).
212	        if (to.equals("OPEN") && found.status().equals("DRAFT")) {
213	            BigDecimal threshold = settings.reviewThreshold(id, LocalDate.parse(found.date()));
214	            BigDecimal now = repository.dueNow(id, found);
215	            if (threshold != null && now != null && now.compareTo(threshold) > 0) {
216	                to = "REVIEW";
217	                event = "CLAIM_REVIEW";
218	            }
219	        }
220	        // Settled as of a date: on or before the sheet's today, and only a claim that existed then; its due is the one
221	        // it had at the end of that day, worked out as the as-of view does.
222	        BigDecimal asOfDue = null;
223	        if (on != null && to.equals("SETTLED")) {
224	            if (on.isAfter(settings.today(id))) {
225	                throw new BadRequestException("a claim cannot be settled as of a date after the sheet's today");
226	            }
227	            BigDecimal[] then = view.readAt(id, on, () -> {
228	                Claim was = repository.find(id, cid);
229	                return was == null ? null : new BigDecimal[] { repository.dueNow(id, was) };
230	            });
231	            if (then == null) {
232	                throw new BadRequestException("the claim did not exist on " + on);
233	            }
234	            asOfDue = then[0];
235	        }
236	        if (checkOnly) {
237	            return null;
238	        }
239	        Rollup.Snapshot before = rollup.take(id);
240	        if (!repository.changeStatus(id, cid, from, to)) {
241	            throw new BadRequestException("a " + found.status() + " claim cannot be moved to " + to);
242	        }
243	        if (voidReason != null) {
244	            repository.voidReason(id, cid, voidReason);
245	        }
246	        if (to.equals("REVIEW")) {
247	            repository.reviewDay(id, cid);
248	        }
249	        // Opening gives the sheet's next number; a rejected claim keeps its own; a voided claim keeps the number it had (never reused).
250	        String number = found.number();
251	        String openedBy = found.openedBy();
252	        if ((found.status().equals("DRAFT") || found.status().equals("REVIEW")) && to.equals("OPEN")) {
253	            number = repository.numbersPerPeriod(id)
254	                    ? repository.numberInPeriod(id, cid, LocalDate.parse(found.dueBy()))
255	                    : repository.number(id, cid, LocalDate.parse(found.dueBy()));
256	        }
257	        // Who opened it is recorded when it is opened, also when it went to REVIEW; a review keeps it.
258	        if (found.status().equals("DRAFT") && (to.equals("OPEN") || to.equals("REVIEW"))) {
259	            repository.openedBy(id, cid, by);
260	            openedBy = by;
261	        }
262	        // Settling (or approving) fixes the claim's due as it is now: the figure its last statement bound it to,
263	        // else its live due ('n/a' when its grade has no rate, which stays live), with its late charge frozen in.
264	        String due = null;
265	        String tail = event.equals("CLAIM_REJECTED") ? " reason=" + why : "";
266	        if (reversing) {
267	            tail = " reversed=" + (found.due() == null ? "n/a" : found.due());
268	        }
269	        if (voidReason != null) {
270	            tail += " reason=" + voidReason;
271	        }
272	        if (to.equals("SETTLED")) {
273	            BigDecimal now = on != null ? asOfDue : repository.dueNow(id, found);
274	            repository.settleDue(id, cid, now);
275	            due = ClaimRepository.dueOf(now);
276	            tail = " due=" + (due == null ? "n/a" : due);
277	            if (on != null) {
278	                tail += " on=" + on;
279	            }
280	        }
281	        repository.log(id, cid, by);
282	        Claim changed = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(), to,
283	                number, due, openedBy, found.stated(), found.statedDue(), found.corrects(), found.dueBy(),
284	                found.statedNa(), found.deferredUntil(), found.deferred(), found.proofs(), found.splitFrom(), found.lateEntry(), found.reminded(), found.ref(), found.tags(),
285	                voidReason != null ? voidReason : found.voidReason(), found.waived(), found.photos(), found.held());
286	        if (found.status().equals("REVIEW") && to.equals("OPEN")) {
287	            audit.record("CLAIM_REVIEWED sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
288	                    + " amount=" + changed.amount() + " date=" + changed.date());
289	        }
290	        audit.record(event + " sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
291	                + " amount=" + changed.amount() + " date=" + changed.date() + Claim.auditNumber(number) + tail);
292	        // A settled (or approved) claim's watchers are told, after the claim's own line and before the rollup.
293	        if (event.equals("CLAIM_SETTLED") || event.equals("CLAIM_APPROVED")) {
294	            watches.notify(id, found.personId(), repository.personName(id, found.personId()), number, by, audit);
295	        }
296	        rollup.record(id, by, before);
297	        return changed;
298	    }
299	
300	    /** A steward re-settles a SETTLED claim (not in a closed period): its due is frozen again at the figure it would
301	     *  have today as an open claim bound by no statement (today's rates, grades, floor and late charge). */
302	    private static Claim resettle(String id, long cid, String by, ClaimRepository repository, PeriodRepository periods,
303	            SettingsRepository settings, Audit audit, Rollup rollup, WatchRepository watches) throws BadRequestException {
304	        Claim found = repository.find(id, cid);
305	        if (found == null) {
306	            throw new BadRequestException("no such claim");
307	        }
308	        if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
309	            throw new BadRequestException("only a steward can re-settle a claim");
310	        }
311	        if (!found.status().equals("SETTLED")) {
312	            throw new BadRequestException("only a SETTLED claim can be re-settled");
313	        }
314	        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
315	        Claim live = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(), "OPEN",
316	                found.number(), null, found.openedBy(), false, null, found.corrects(), found.dueBy(), false, null, false, found.proofs(), found.splitFrom(), found.lateEntry(), found.reminded(), found.ref(), found.tags(), found.voidReason(), found.waived(), found.photos(), found.held());
317	        BigDecimal now = repository.dueNow(id, live);
318	        Rollup.Snapshot before = rollup.take(id);
319	        repository.settleDue(id, cid, now);
320	        repository.log(id, cid, by);
321	        String old = found.due() == null ? "n/a" : found.due();
322	        String due = ClaimRepository.dueOf(now);
323	        Claim changed = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(),
324	                found.status(), found.number(), due, found.openedBy(), found.stated(), found.statedDue(),
325	                found.corrects(), found.dueBy(), found.statedNa(), found.deferredUntil(), found.deferred(), found.proofs(), found.splitFrom(), found.lateEntry(), found.reminded(), found.ref(), found.tags(), found.voidReason(), found.waived(), found.photos(), found.held());
326	        audit.record("CLAIM_RESETTLED sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
327	                + " amount=" + changed.amount() + " date=" + changed.date() + Claim.auditNumber(found.number())
328	                + " old=" + old + " new=" + (due == null ? "n/a" : due));
329	        watches.notify(id, found.personId(), repository.personName(id, found.personId()), found.number(), by, audit);
330	        rollup.record(id, by, before);
331	        return changed;
332	    }
333	}
